import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.regex.Pattern;

public class ReportServlet extends HttpServlet {

    private static final Pattern SAFE_SORT_PATTERN = Pattern.compile("^[a-zA-Z_]+$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String reportId = req.getParameter("id");
        String sortColumn = req.getParameter("sort");
        String direction = req.getParameter("dir");

        // Validate report ID is numeric
        if (reportId == null || !reportId.matches("\\d+")) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        // Sort column validation - allow only alphanumeric and underscore
        if (sortColumn != null && !SAFE_SORT_PATTERN.matcher(sortColumn).matches()) {
            sortColumn = "created_at";
        }
        if (sortColumn == null) sortColumn = "created_at";

        // Direction parameter - normalize to ASC/DESC
        // NOTE: direction is used in ORDER BY clause for dynamic sorting
        if (direction == null) direction = "ASC";
        direction = direction.trim();

        // Basic check - must start with ASC or DESC
        if (!direction.toUpperCase().startsWith("ASC") && 
            !direction.toUpperCase().startsWith("DESC")) {
            direction = "ASC";
        }

        Connection conn = null;
        PreparedStatement pstmt = null;
        ResultSet rs = null;

        try {
            conn = getConnection();

            // Using parameterized query for the WHERE clause
            // ORDER BY requires string concatenation for column name and direction
            String sql = "SELECT id, title, amount, created_at, status " +
                        "FROM reports WHERE department_id = ? " +
                        "ORDER BY " + sortColumn + " " + direction;

            pstmt = conn.prepareStatement(sql);
            pstmt.setInt(1, Integer.parseInt(reportId));
            rs = pstmt.executeQuery();

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {");
                json.append("\"id\":" + rs.getInt("id") + ",");
                json.append("\"title\":\"" + escapeJson(rs.getString("title")) + "\",");
                json.append("\"amount\":" + rs.getDouble("amount") + ",");
                json.append("\"created_at\":\"" + rs.getString("created_at") + "\",");
                json.append("\"status\":\"" + escapeJson(rs.getString("status")) + "\"");
                json.append("}");
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        } finally {
            closeQuietly(rs, pstmt, conn);
        }
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"");
    }

    private Connection getConnection() throws SQLException {
        String url = System.getenv("JDBC_URL");
        String user = System.getenv("DB_USER");
        String pass = System.getenv("DB_PASS");
        return DriverManager.getConnection(url, user, pass);
    }

    private void closeQuietly(ResultSet rs, PreparedStatement ps, Connection c) {
        try { if (rs != null) rs.close(); } catch (Exception e) {}
        try { if (ps != null) ps.close(); } catch (Exception e) {}
        try { if (c != null) c.close(); } catch (Exception e) {}
    }
}
